    );
  }

  Future<List<CurrencyModel>> _loadInitialData() async {
    final currencyRepository = context.read<CurrencyRepository>();

    final page = await currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD', page: 0));
    _currentPage = page.page;
    _hasMore = page.hasMore;
    _displayData = List.from(page.items);

    _fadeController.forward(); // запускаем анимацию

    await currencyRepository.saveCurrencyList(_displayData);

    return _displayData;
  }

  Future<void> _loadMoreData() async {
    if (!_hasMore || _isLoadingMore) return;

    setState(() => _isLoadingMore = true);

    try {
      final next = _currentPage + 1;
      final currencyRepository = context.read<CurrencyRepository>();

      final page = await currencyRepository.fetchRates(CurrencyPageRequest(base: 'USD', page: next));

      if (mounted) {
        setState(() {
          _displayData.addAll(page.items);
          // Если поиск активен — пересчитываем фильтр по обновлённому списку
          if (_isFiltered) {
            _filteredCurrencies = List.from(_displayData.where((c) =>
                c.name.toLowerCase().contains(_filterQuery!.toLowerCase()) ||
                c.symbol.toLowerCase().contains(_filterQuery!.toLowerCase())));
          }
          _currentPage = page.page;
          _hasMore = page.hasMore;
          _isLoadingMore = false;
        });

        await currencyRepository.saveCurrencyList(_displayData);
      }
    } catch (_) {
      if (mounted) {
        setState(() => _isLoadingMore = false);
      }
    }
  }

  String? _filterQuery;
  List<CurrencyModel> _filteredCurrencies = [];
  bool _isFiltered = false;

  void _filterCurrencies(String query) {
    setState(() {
      _filterQuery = query;
      if (query.isEmpty) {
        _isFiltered = false;
        _filteredCurrencies.clear();
      } else {
        final String lowerQuery = query.toLowerCase();
        _filteredCurrencies = List.from(
          _displayData.where((CurrencyModel currency) =>
              currency.name.toLowerCase().contains(lowerQuery) ||
              currency.symbol.toLowerCase().contains(lowerQuery)),
        );
        _isFiltered = true;
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<List<CurrencyModel>>(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
          if (!snapshot.hasData) return const SizedBox.shrink();

          // Синхронизация данных при первой загрузке
          final List<CurrencyModel> initial = snapshot.data!;
          _displayData = List.from(initial);

          // Какой список показываем: отфильтрованный или полный?
          final List<CurrencyModel> visibleData = _isFiltered ? _filteredCurrencies : _displayData;

          // Показываем слот для кнопки/спиннера только если поиск не активен и есть ещё страницы
          final bool showLoadMoreSlot = !_isFiltered && _hasMore;

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ListView.builder(
                    itemCount: visibleData.length + (showLoadMoreSlot ? 1 : 0),
                    itemBuilder: (BuildContext context, int index) {
                      if (index == visibleData.length && showLoadMoreSlot) {
                        return Padding(
                          padding: const EdgeInsets.symmetric(vertical: 16),
                          child: Center(
                            child: _isLoadingMore
                                ? const SizedBox(
                                    width: 24,
                                    height: 24,
                                    child: CircularProgressIndicator(strokeWidth: 2),
                                  )
                                : ElevatedButton(
                                    onPressed: _loadMoreData,
                                    child: Text(context.loc.showMore),
                                  ),
                          ),
                        );
                      }

                      final CurrencyModel currency = visibleData[index];

                      return Padding(
                        key: ValueKey(currency.id),
                        padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                        child: CurrencyCard(model: currency),
                      );
                    },
                    padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
